    local isPass = BambooUtils.IsPassMap(self._data.id)
    local isUnlock, str = BambooUtils.IsUnlockMap(self._data.id, self._activityUuid)

    --[[
    CfUtils.SetActive(self.Imgbg1, not isUnlock)
    CfUtils.SetActive(self.Imgbg2, isUnlock and not isPass)
    CfUtils.SetActive(self.Imgbg3, isPass)
    ]]
