--当前挑战的动画
function UIBambooMainMapPointNode:PlayAnimator1()
    if self._openCo then
        cs_coroutine.stop(self._openCo)
        self._openCo = nil
    end
    local animator = self.Root:GetComponent(typeof(Animator))
    self._openCo = cs_coroutine.start(function()
        coroutine.yield(animator.PlayAndWait(animator, Animator.StringToHash("Open")))
        KTool.SetActive(self.Fight, true)
    end)
end

--打完的动画
function UIBambooMainMapPointNode:PlayAnimator2()
    if self._closeCo then
        cs_coroutine.stop(self._closeCo)
        self._closeCo = nil
    end
    local animator = self.Root:GetComponent(typeof(Animator))
    self._closeCo = cs_coroutine.start(function()
        self:FillBattingImg()
        coroutine.yield(animator.PlayAndWait(animator, Animator.StringToHash("Finish")))
        self:FillNormalImg()
        KTool.SetActive(self.Imgbg1, true)
        KTool.SetActive(self.Imgbg2, false)
        CfUtils.FillImage(self.Imglabel, activity_btn_chapter_img_finsh02, true)
        KTool.SetActive(self.Point, false)
    end)
end

function UIBambooMainMapPointNode:FillBattingImg()
    CfUtils.FillImage(self.ImgIcon, string.format(battleingPath, self._data.id), true)
end

function UIBambooMainMapPointNode:FillNormalImg()
    CfUtils.FillImage(self.ImgIcon, string.format(normalPath, self._data.id), true)
end

--
function UIBambooMainMapPointNode:OnClick()
    if not self._cb then
        return
    end
    self._cb()
end

function UIBambooMainMapPointNode:OnDestroy()
    if self._openCo then
        cs_coroutine.stop(self._openCo)
        self._openCo = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIBambooMainMapPointNode
